effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }

vec3 rgb2hsv(vec3 c){
  vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1.0e-6;
  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c){
  vec3 p = abs(fract(c.xxx + vec3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0);
  return c.z * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), c.y);
}
void main(){
vec4 src = tex(acScreenNorm);
vec3 hsv = rgb2hsv(clamp(src.rgb, 0.0, 1.0));
float d = abs(fract(hsv.x - center / 360.0 + 0.5) - 0.5) * 360.0;
float wgt = 1.0 - smoothstep(range * 0.5, range, d);
hsv.x = fract(hsv.x + (hueShift / 360.0) * wgt);
hsv.y = clamp(hsv.y * mix(1.0, satScale, wgt), 0.0, 4.0);
hsv.z = clamp(hsv.z * mix(1.0, lightScale, wgt), 0.0, 4.0);
vec3 c = hsv2rgb(hsv);
gl_FragColor = vec4(mix(src.rgb, c, mixAmt), src.a);
}
